import { ref, nextTick } from 'vue';
import axios from 'axios';
import { ElMessage } from 'element-plus';
import DockerContainers from '@/components/Container/DockerContainers.vue';
export default {
  __name: 'ClearFirewallRuleDialog',
  setup(__props, {
    expose: __expose
  }) {
    const dialogVisible = ref(false);
    const containerName = ref('');
    const containers = ref([]);
    const containersRef = ref(null);

    // 弹窗打开时初始化
    const openDialog = async () => {
      dialogVisible.value = true;
      containerName.value = ''; // 重置容器名称
      await nextTick();
      if (containersRef.value) {
        await containersRef.value.fetchContainers();
        containers.value = containersRef.value.containers || [];
      }
    };
    __expose({
      openDialog
    });

    // 清空防火墙规则
    const handleClearAll = async () => {
      if (!containerName.value) {
        ElMessage.warning('请选择容器');
        return;
      }
      try {
        await axios.delete('http://localhost:8081/firewall/clearAll', {
          params: {
            containerName: containerName.value
          }
        });
        ElMessage.success('规则已成功清空');
        dialogVisible.value = false;
      } catch (err) {
        ElMessage.error(`清空规则失败：${err?.response?.data || err.message}`);
      }
    };

    // 弹窗关闭时重置表单
    const resetForm = () => {
      containerName.value = '';
    };
    const __returned__ = {
      dialogVisible,
      containerName,
      containers,
      containersRef,
      openDialog,
      handleClearAll,
      resetForm,
      ref,
      nextTick,
      get axios() {
        return axios;
      },
      get ElMessage() {
        return ElMessage;
      },
      DockerContainers
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
